    tool: checklist('平台发现试点的五项检查', 'Five checks for a discovery pilot', [['用相同社区问题测试每个平台','Test each platform with the same community problem'],['保存搜索词和原内容链接','Retain queries and original content links'],['区分受众证据、估计与未知','Separate audience evidence, estimates and unknowns'],['合并重复账号但保留不同平台记录','Deduplicate identities while retaining channel records'],['写明继续试点与停止试点的条件','Document continuation and stop conditions']]),
    sources: [evidence.discovery, evidence.overlap],
